from scipy.optimize import least_squares
Ds=[load('train/A2_vref_op1.csv'),load('train/A2_load_op2.csv')]
def resid(p):
    r=[]
    for D in Ds:
        o=sim(p,D); r.append(np.r_[(o[:,0]-D['P']),(o[:,1]-D['Q'])])
    return np.concatenate(r)
best=None
for XL0 in [0.1,0.2,0.3]:
  for kpv0 in [0.5,2.0]:
    p0=[XL0,0.03,0.05,5.0,kpv0,0.01,0.01,0.01]
    lb=[0.02,0.001,0.0,0.5,0.0,0.001,0.001,0.001]; ub=[0.4,0.2,0.3,30,50,0.1,0.1,0.1]
    try:
        r=least_squares(resid,p0,bounds=(lb,ub),x_scale='jac',max_nfev=40)
    except Exception as e: print(e); continue
    c=np.sqrt(np.mean(r.fun**2)); print(XL0,kpv0,np.round(r.x,4),round(c,5))
    if best is None or c<best[0]: best=(c,r.x)
np.save('p_best.npy',best[1]); print('best',best)

