import numpy as np, json
p=np.load('p_b.npy')
XL,mp,mq,kiv,kpv,TPf,TQf,TVf=[float(x) for x in p]
sub={
 "params":{"XL":XL,"mp":mp,"mq":mq,"kiv":kiv,"kpv":kpv,"TPf":TPf,"TQf":TQf,"TVf":TVf,"w0":2*np.pi*60},
 "defs":{
   "Er":"V0+XL*Q0/V0",
   "Ei":"XL*P0/V0",
   "E0":"sqrt(Er**2+Ei**2)",
   "Vcmd":"Vset-mq*(Qm-Q0)",
   "Eint":"Min(Max(kpv*(Vcmd-Vm)+xv,0),1.5)",
   "P":"V*Eint*sin(delta-theta)/XL",
   "Q":"(Eint*V*cos(delta-theta)-V**2)/XL"
 },
 "states":{
   "Pm":{"rhs":"(P-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q-Qm)/TQf","init":"Q0"},
